import React, { useEffect, useState } from "react";
import axios from "axios";

const AddCardtask = ({prop}) => {

    const [res, setRes] = useState(null);
    const [name,setName] = useState("");
    const handleInputTask = (e) => {
        setName(e.target.value);
    }

    const putTask = async () => {
        try {
            const result = await axios.post('http://localhost:3001/api/task',{name: name, daycreate: 1, daytarget: 2, deadline: 3, state: "green", id_project: prop.project.id});
            setRes(result.data);
        } catch (error) {
            console.error('Ошибка получения данных:', error);
        } 
    }

    const handleInsertTask = () => {
        if(name){
            putTask();
        }
    }

    const handleRepeal = () => {
        prop.setTarg(false);
    }

    useEffect(() => {
        if(!!res){
        console.log(res.id);
        prop.tasks.push({})
        prop.setTarg(false);
        }
    }, [res]);

    return (
        <div className="AddCardTask">
            <input className="inputNewTask" onChange={handleInputTask}></input>
            <button className="buttonInsertTask" onClick={handleInsertTask}>ОК</button>
            <button className="buttonRepeal" onClick={handleRepeal}>ОТМЕНА</button>
        </div>
    )
}

export default AddCardtask;
